<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {usePhasePage} from '../phasePage'
import {WorkforceApiError} from '../api'
import {captureLocation,requiresLocation,useWorkModeText,type ClockLocation} from '../workMode'
import {resolveClockPolicy} from '../clockPolicy'
import type {ClockAction,ClockResult} from '../types'
import {hours,localInput} from '../time'
import {punchBreaks,reviewText} from '../attendanceReview'
import BreakSummaryTable from '../components/BreakSummaryTable.vue'
import ClockLocationCheck from '../components/ClockLocationCheck.vue'
import PhaseStatus from '../components/PhaseStatus.vue'
const {api,home,store,current,t,p,base,loading,busy,failure,notice,load,write,format,english}=usePhasePage(),data=ref<ClockResult|null>(null),selected=ref(''),breakRuleId=ref(''),storageReady=ref(true)
const {w}=useWorkModeText(),locating=ref(false),description=ref('')
type Pending={commandId:string;action:ClockAction;scheduleId:string;breakRuleId?:string|null;location?:ClockLocation|{description:string}}
const policy=computed(()=>resolveClockPolicy(data.value,selected.value))
const pending=ref<Pending|null>(null),storageKey=`rpb.workforce.clock:${home.value?.myself?.accountId||''}:${store.value}`
const otherStore=computed(()=>!!data.value?.active&&data.value.active.storeId!==store.value),zone=computed(()=>data.value?.attendance?.schedule.timezone||data.value?.schedules[0]?.timezone||'Asia/Singapore')
const completedToday=computed(()=>{const value=data.value;return !!value?.attendance?.session?.outAt&&value.attendance.schedule.workDate===localInput(value.serverTime,value.attendance.schedule.timezone).slice(0,10)})
const shift=computed(()=>{const id=data.value?.active?.scheduleId||selected.value;return data.value?.schedules.find(s=>s.id===id)?.shift||(data.value?.attendance?.schedule.id===id?data.value.attendance.schedule.shift:undefined)}),breakRules=computed(()=>punchBreaks(shift.value)),r=(key:Parameters<typeof reviewText>[0])=>reviewText(key,english())
function refresh(){void load(()=>api().get<ClockResult>('/clock'),v=>{data.value=v;if(!v.schedules.some(s=>s.id===selected.value))selected.value=v.schedules.length===1?v.schedules[0]!.id:''})}
function clear(){sessionStorage.removeItem(storageKey);pending.value=null}
async function act(action?:ClockAction){if(busy.value||locating.value||!storageReady.value)return;if(!pending.value){const scheduleId=data.value?.active?.scheduleId||selected.value;if(!action||!scheduleId||otherStore.value||policy.value?.mode==='free'||!data.value?.actions.includes(action))return;if(action==='BREAK_START'&&shift.value?.rules&&!breakRules.value.some(b=>b.id===breakRuleId.value))return;const command:Pending={commandId:crypto.randomUUID(),action,scheduleId,...(action==='BREAK_START'?{breakRuleId:breakRuleId.value||null}:action==='BREAK_END'?{breakRuleId:data.value?.active?.breakStartedRuleId||null}:{})};if(requiresLocation(policy.value)){locating.value=true;failure.value='';try{const location=await captureLocation(description.value);if(!current())return;if(policy.value?.point&&location.accuracyMeters>policy.value.point.radiusMeters)throw new Error('LOCATION_ACCURACY');command.location=location}catch{failure.value=w('locationError');return}finally{locating.value=false}}else if(policy.value?.mode==='field'&&description.value.trim()){command.location={description:description.value}}
try{sessionStorage.setItem(storageKey,JSON.stringify(command));pending.value=command}catch{storageReady.value=false;failure.value=p('storageError');return}}
 const command=pending.value!;await write(async()=>{try{await api().put('/clock/'+command.commandId,{scheduleId:command.scheduleId,action:command.action,...(command.breakRuleId!==undefined?{breakRuleId:command.breakRuleId}:{}),...(command.location?{location:command.location}:{})});clear()}catch(e){if(e instanceof WorkforceApiError&&e.status>=400&&e.status<500)clear();throw e}},refresh)
}
onMounted(()=>{try{const raw=sessionStorage.getItem(storageKey);if(raw){const value=JSON.parse(raw);if(typeof value.commandId==='string'&&typeof value.scheduleId==='string'&&['IN','OUT','BREAK_START','BREAK_END'].includes(value.action))pending.value=value;else throw new Error('invalid recovery record')}}catch{storageReady.value=false;failure.value=p('storageError')}if(home.value?.myself)refresh()})
</script>
<template><section class="wf-panel wf-form-panel"><header class="wf-toolbar"><h2>{{p('clock')}}</h2><button :disabled="busy||loading||locating" @click="refresh">{{t('refresh')}}</button></header><p class="wf-hint">{{w('locationHint')}}</p><p v-if="!home?.myself">{{t('missingProfile')}}</p><p v-if="!storageReady" role="alert" class="wf-error">{{p('storageError')}}</p><PhaseStatus :failure="failure" :notice="notice" :loading="loading"/><RouterLink v-if="home?.myself" :to="base+'/work-mode'">{{w('title')}}</RouterLink><template v-if="data&&!loading"><p v-if="policy?.mode==='free'" role="status">{{w('freeHint')}}</p><p v-if="requiresLocation(policy)&&!policy?.point" role="status">{{w('missingPoint')}}</p><ClockLocationCheck v-if="requiresLocation(policy)&&policy?.point" :store-id="store" :point="policy.point" :disabled="busy||locating||!!pending"/><label v-if="policy?.mode==='field'">{{w('description')}}<input v-model="description" maxlength="200" :disabled="busy||!!pending"></label><p v-if="otherStore" role="status">{{p('otherStore')}} <RouterLink :to="`/stores/${encodeURIComponent(data.active!.storeId)}/workforce/clock`">{{p('goStore')}}</RouterLink></p><template v-else><p v-if="data.active" class="wf-badge">{{p(data.active.breakStartedAt?'resting':'working')}}<span v-if="data.active.breakStartedRuleId"> · {{breakRules.find(b=>b.id===data!.active!.breakStartedRuleId)?.name}}</span></p><label v-if="!data.active&&policy?.mode!=='free'">{{p('shift')}}<select v-model="selected" :disabled="busy||locating||!!pending||!storageReady"><option value="" disabled>{{t('select')}}</option><option v-for="s in data.schedules" :key="s.id" :value="s.id">{{s.shift.name}} · {{format(s.startAt,s.timezone)}}–{{format(s.endAt,s.timezone)}}</option></select></label><p v-if="!data.active&&policy?.mode!=='free'&&!data.schedules.length" class="wf-empty">{{p(completedToday?'completed':'noSchedule')}}</p><label v-if="!pending&&data.actions.includes('BREAK_START')&&breakRules.length">{{r('selectBreak')}}<select v-model="breakRuleId" :disabled="busy||locating"><option value="" disabled>{{t('select')}}</option><option v-for="b in breakRules" :key="b.id" :value="b.id">{{b.name}}</option></select></label><div v-if="!pending&&policy?.mode!=='free'" class="wf-inline wf-section"><button v-for="action in data.actions" :key="action" class="primary" :disabled="busy||locating||!storageReady||(action==='IN'&&!selected)||(action==='BREAK_START'&&!!shift?.rules&&!breakRules.some(b=>b.id===breakRuleId))" @click="act(action)">{{locating?w('locating'):busy?t('saving'):p(action)}}</button></div></template><dl v-if="data.attendance" class="wf-details"><dt>{{p('inAt')}}</dt><dd>{{format(data.attendance.session?.inAt,zone)}}</dd><dt>{{p('outAt')}}</dt><dd>{{format(data.attendance.session?.outAt,zone)}}</dd><dt>{{p('workHours')}}</dt><dd>{{hours(data.attendance.workSeconds)}}</dd><dt>{{p('detail')}}</dt><dd><RouterLink :to="base+'/attendance/'+data.attendance.schedule.id">{{p('attendance')}}</RouterLink></dd></dl><template v-if="data.attendance"><BreakSummaryTable :summaries="data.attendance.breakSummary"/></template><p class="wf-hint">{{p('timezone')}}: {{zone}} · {{format(data.serverTime,zone)}}</p></template><div v-if="pending" class="wf-section"><p role="status">{{p('pendingAction')}} {{p(pending.action)}}</p><button class="primary" :disabled="busy||!storageReady" @click="act()">{{busy?t('saving'):p('recover')}}</button></div><p class="wf-hint">{{p('factsHint')}}</p></section></template>



